Page_CommonActSignInView = class("Page_CommonActSignInView",Page_CommonActViewBase)

function Page_CommonActSignInView:GetPageName()
    return "Page_CommonActSignInView"
end

function Page_CommonActSignInView:initialize()

end

function Page_CommonActSignInView:OnAwake()
    self.ScrollView = UIUtil.GetTypeChildWightInputPath("ScrollView", self.gameObject, typeof(MoreRowScrollView))
end

function Page_CommonActSignInView:RequestOpen()
    ActSignInDataManager:Get():SetCurActSignInId(self.actConfig.C_ID)
    CommonFestivalSubSystem:Get():SendMsg_SignInfo(self.actConfig.C_ID)
end

function Page_CommonActSignInView:OnOpen()
    self:Refresh()
end

function Page_CommonActSignInView:Refresh()
    local timeTxt = self:GetDataTimeString()
    CommonHelper:SetText("time/###time", self.gameObject, timeTxt)

    CommonHelper:InitMoreRowScrollView(self.ScrollView, ActSignInDataManager:Get():GetTotalDays(), 1,function(dataIndex, itemObj, scroll)
        self:UpdateScrollView(itemObj,dataIndex)
    end,false,nil,ActSignInDataManager:Get():GetActSignIsResetFlag())
    local moveIndex = ActSignInDataManager:Get():GetNowDay()
    local totalDay = ActSignInDataManager:Get():GetTotalDays()
    moveIndex=moveIndex>totalDay and totalDay or moveIndex
    if moveIndex == totalDay then
        moveIndex = totalDay-4
    elseif moveIndex > totalDay -4 then
        moveIndex =  totalDay -5
    else
        moveIndex = moveIndex-2
        moveIndex = moveIndex<1 and 1 or moveIndex
    end
    if ActSignInDataManager:Get():GetActSignIsResetFlag() then
        CommonHelper:MoreRowView_ScrollToItem(self.ScrollView,moveIndex-1)
    end
end

function Page_CommonActSignInView:UpdateScrollView(itemObj,dataIndex)
    local actSignInData = ActSignInDataManager:Get():GetCurActSignIn()
    local day = dataIndex+1
    local redStyle = day%2 == 1
    local signInState=actSignInData:GetStateByDay(day)
    CommonHelper:SetGameObjectActive("yellowUnSignInBg",itemObj,(not redStyle)  )
    CommonHelper:SetGameObjectActive("yellowGrayBg",itemObj,(not redStyle) and signInState==SignInState.SignedIn)
    CommonHelper:SetGameObjectActive("redUnSignInBg",itemObj, redStyle )
    CommonHelper:SetGameObjectActive("redGrayBg",itemObj, redStyle and signInState==SignInState.SignedIn)
    CommonHelper:SetGameObjectActive("signInBtn",itemObj,signInState == SignInState.NoSignIn)
    CommonHelper:SetGameObjectActive("retroactiveBtn",itemObj,signInState == SignInState.Retroactive)

    local daystr = ""
    if day < 10 then
        daystr = "0" .. day
        CommonHelper:SetText("yellowUnSignInBg/###dayNum", itemObj, daystr)
        CommonHelper:SetText("redUnSignInBg/###dayNum", itemObj, daystr)
    else
        CommonHelper:SetText("yellowUnSignInBg/###dayNum", itemObj, day)
        CommonHelper:SetText("redUnSignInBg/###dayNum", itemObj, day)
    end

    CommonHelper:HButtonSetCallback("signInBtn",itemObj,function()
        CommonFestivalSubSystem:Get():SendMsg_SignNow(self.actConfig.C_ID,day,0)
    end)
    CommonHelper:HButtonSetCallback("retroactiveBtn",itemObj,function()
        local playerDiamond = PlayerDataManager:Get():GetCurrency(CurrencyType.Diamond)
        if actSignInData:GetExpPay() > playerDiamond  then
            CommonTipsHelper:ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.RetroactiveMonthSignCostNotEnough))
        else
            local boxFunc = function()
                local str= string.format(CommonHelper:GetTempStr_Default(TemplateStringID.RetroactiveMonthSignCostTip),actSignInData:GetExpPay())
                local ret = MessageBoxHelp:Get():OpenBox_OKCancel(UIColor.Blue, str)
                if ret == MessageBoxHelp.BtnType.OK then
                    CommonFestivalSubSystem:Get():SendMsg_SignNow(self.actConfig.C_ID,day,1)
                end
            end
            MessageBoxHelp.Get():StartCoroutineBox(boxFunc)
        end
    end)
    local rewardItemGroup=UIUtil.GetChild("ItemGroup",itemObj)
    local count = rewardItemGroup.transform.childCount
    for i = 1, count do
        local rewardItemObj = rewardItemGroup.transform:GetChild(i-1).gameObject
        local rewardData =  actSignInData:GetRewardData(day,i)
        if rewardData then
            CommonHelper:CSGameObjectSetActive(rewardItemObj,true)
            CommonHelper:HButtonSetCallback("ItemBtn",rewardItemObj,function()
                CommonHelper:ShowRewardPopup({rewardData},ClientDataManager:Get():GetTemplateString(TemplateStringID.RewardPreview))
            end)
            local propType ,configData = CommonHelper:GetPropTypeById(tonumber(rewardData.id))
            local name =""
            if propType==PropType.TracKSegment then
                name = configData.name
            elseif propType==PropType.Part then
                name=configData.partname
            elseif propType==PropType.Article then
                name=configData.name
            end
            --CommonHelper:SetText("yellowUnSignInBg/###itemNum_"..i,itemObj,string.format(CommonHelper:GetTempStr_Default(TemplateStringID.LuckRotaryAwardPublicity),ClientDataManager:Get():GetTemplateString(name) ,rewardData.num))
            --CommonHelper:SetText("redUnSignInBg/###itemNum_"..i,itemObj,string.format(CommonHelper:GetTempStr_Default(TemplateStringID.LuckRotaryAwardPublicity),ClientDataManager:Get():GetTemplateString(name) ,rewardData.num))
            local param = Param_ItemArticleParam()
            param.count = rewardData.num
            CommonHelper:SetItemComGroup(rewardItemObj, UIModuleID.CommonActSignIn, rewardData.id, param, function(btnData)
                CommonHelper:ShowPartInfoByCfgId(btnData, UIModuleID.CommonActSignIn, false)
            end, rewardData.id)
        else
            CommonHelper:CSGameObjectSetActive(rewardItemObj,false)
            --CommonHelper:SetText("yellowUnSignInBg/###itemNum_"..i,itemObj,"")
            --CommonHelper:SetText("redUnSignInBg/###itemNum_"..i,itemObj,"")
        end
    end
end

function Page_CommonActSignInView:GetRedPointActive()
    return RedPointManager:Get():GetValue(RedPointID.S_SpringSignIn)
end